import java.util.Scanner;

public class Main {
    static final int maxn = 512;
    static long[][] c = new long[maxn][maxn];
    static long[][] p = new long[maxn][maxn];
    static long n, m, M;
    static long sum, val;

    static long g(int a, int b) {
        if (b == 0) return 1;
        return p[a + 1][b - 1] * p[2][b] % M * (a + 1 - b) % M;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextLong();
        m = sc.nextLong();
        M = sc.nextLong();

        for (int i = 0; i < maxn; ++i) {
            c[i][0] = 1;
            for (int j = 1; j <= i; ++j) {
                c[i][j] = (c[i - 1][j] + c[i - 1][j - 1]) % M;
            }
        }

        for (int i = 0; i < maxn; ++i) {
            p[i][0] = 1;
            for (int j = 1; j < maxn; ++j) {
                p[i][j] = p[i][j - 1] * i % M;
            }
        }

        sum = 0;
        for (int i = 2; i <= m; ++i) {
            for (int d = 1; d < i; ++d) {
                long temp1 = d * (d + 1) / 2 % M;
                long temp2 = c[i - 1][d];
                long temp3 = p[d + 1][d - 1];
                long temp4 = g((int)n - d - 1, i - d);
                long temp5 = p[2][d];
                long temp6 = p[(int)(n + 1 - (d + 1))][m - i];
                long temp7 = p[2][m - i];

                val = temp1 * temp2 % M * temp3 % M * temp4 % M * temp5 % M * temp6 % M * temp7 % M;
                sum = (sum + 2 * val) % M;
            }
        }

        System.out.println((sum * (n + 1 - m) % M));
        sc.close();
    }
}
